from typing import List

class Solution:
    def maximumCoins(self, coins: List[List[int]], k: int) -> int:
        coins.sort()
        n = len(coins)
        ans = 0

        j = 0
        cur = 0
        for i in range(n):
            start = coins[i][0]
            end = start + k - 1

            if j < i:
                j = i
                cur = 0

            while j < n and coins[j][1] <= end:
                cur += (coins[j][1] - coins[j][0] + 1) * coins[j][2]
                j += 1

            total = cur
            if j < n and coins[j][0] <= end:
                total += (end - coins[j][0] + 1) * coins[j][2]

            ans = max(ans, total)

            if j > i:
                cur -= (coins[i][1] - coins[i][0] + 1) * coins[i][2]

        j = n - 1
        cur = 0
        for i in range(n - 1, -1, -1):
            end = coins[i][1]
            start = end - k + 1

            if j > i:
                j = i
                cur = 0

            while j >= 0 and coins[j][0] >= start:
                cur += (coins[j][1] - coins[j][0] + 1) * coins[j][2]
                j -= 1

            total = cur
            if j >= 0 and coins[j][1] >= start:
                total += (coins[j][1] - start + 1) * coins[j][2]

            ans = max(ans, total)

            if j < i:
                cur -= (coins[i][1] - coins[i][0] + 1) * coins[i][2]

        return ans
